rows = [{"score": 2}, {"score": 6}, {}]
values = []
for row in rows:
    value = row.get("score")
    if value is not None:
        values.append(value)
if len(values) > 0:
    mean = sum(values) / len(values)
else:
    mean = None
print(len(values), len(rows), mean)

